<script>
(()=>{const token=document.querySelector('meta[name="csrf-token"]').content;const shippingInput=document.getElementById('shippingInput'),couponInput=document.getElementById('couponInput'),couponField=document.getElementById('couponField'),msg=document.getElementById('couponMessage');const fmt=n=>new Intl.NumberFormat('fa-IR').format(n);async function quote(){const fd=new FormData();fd.append('_token',token);fd.append('shipping',shippingInput.value);if(couponInput.value)fd.append('coupon',couponInput.value);const r=await fetch('{{ route('checkout.quote') }}',{method:'POST',headers:{'Accept':'application/json'},body:fd});const d=await r.json();if(!r.ok)throw new Error(d.message||'خطا در محاسبه');document.getElementById('subtotalValue').textContent=fmt(d.subtotal);document.getElementById('discountValue').textContent=fmt(d.discount);document.getElementById('shippingValue').textContent=fmt(d.shipping);document.getElementById('taxValue').textContent=fmt(d.tax);document.getElementById('totalValue').innerHTML=fmt(d.total)+' <small>تومان</small>';}
document.querySelectorAll('.shipping-option').forEach(b=>b.addEventListener('click',async()=>{document.querySelectorAll('.shipping-option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');shippingInput.value=b.dataset.shipping;try{await quote();msg.textContent='';}catch(e){msg.textContent=e.message;}}));document.getElementById('couponBtn').addEventListener('click',async()=>{couponInput.value=couponField.value.trim().toUpperCase();try{await quote();msg.className='coupon-message ok';msg.textContent='کد تخفیف اعمال شد.';}catch(e){couponInput.value='';msg.className='coupon-message bad';msg.textContent=e.message;}});})();
</script>
